const stripTags = s => { const d=document.createElement("div"); d.innerHTML=s||""; return (d.textContent||"").trim(); };
async function wikiBatch(base, titles, extra){
  const out = [];
  for(let i=0;i<titles.length;i+=40){
    const chunk = titles.slice(i,i+40);
    const r = await fetch(`${base}?action=query&format=json&formatversion=2&origin=*&redirects=1&${extra}&titles=${encodeURIComponent(chunk.join("|"))}`);
    if(!r.ok) throw new Error("wiki "+r.status);
    out.push((await r.json()).query||{});
  }
  return out;
}
async function pageImages(lang, titles){
  const found = {};
  if(!titles.length) return found;
  for(const q of await wikiBatch(`https://${lang}.wikipedia.org/w/api.php`, titles, "prop=pageimages&piprop=thumbnail|name&pithumbsize=900&pilimit=50")){
    const alias = {}; [...(q.normalized||[]),...(q.redirects||[])].forEach(n=>alias[n.from]=n.to);
    const byTitle = {}; (q.pages||[]).forEach(p=>{ if(p.thumbnail&&p.pageimage) byTitle[p.title]={src:p.thumbnail.source,file:p.pageimage.replace(/_/g," "),page:p.title,lang}; });
    titles.forEach(t=>{ let x=t; for(let k=0;k<4&&alias[x];k++) x=alias[x]; if(byTitle[x]) found[t]=byTitle[x]; });
  }
  return found;
}
