async function loadPhotos(){
  try{ const c = JSON.parse(localStorage.getItem(PHOTO_KEY)||"null"); if(c && Date.now()-c.t < 7*864e5){ PHOTO=c.p; render(); return; } }catch(e){}
  try{
    // WIKI 후보 중 "ja:" 로 시작하는 것은 일본어 위키백과 문서
    const wikiAll = Object.values(WIKI).flat();
    const enTitles = [...new Set([...wikiAll.filter(t=>!t.startsWith("ja:")), ...RESTAURANTS.flatMap(dishTitles)])];
    const jaTitles = [...new Set([...wikiAll.filter(t=>t.startsWith("ja:")).map(t=>t.slice(3)), ...RESTAURANTS.flatMap(r=>SHOP_WIKI[r.jp]||[])])];
    const en = await pageImages("en", enTitles);
    let ja = {}; try{ ja = await pageImages("ja", jaTitles); }catch(e){}
    const p = {};
    const wget = t => t.startsWith("ja:") ? ja[t.slice(3)] : en[t];
    Object.entries(WIKI).forEach(([id,ts])=>{ const t=ts.find(wget); if(t) p[id]={...wget(t)}; });
    RESTAURANTS.forEach(r=>{
      const d = dishTitles(r).find(t=>en[t]); if(d) p["dish:"+r.id] = {...en[d]};
      const s = (SHOP_WIKI[r.jp]||[]).find(t=>ja[t]); if(s) p["shop:"+r.id] = {...ja[s]};
    });
    try{
      const files = [...new Set(Object.values(p).map(x=>x.file))].map(f=>"File:"+f);
      const meta = {};
      for(const q of await wikiBatch("https://commons.wikimedia.org/w/api.php", files, "prop=imageinfo&iiprop=extmetadata&iiextmetadatafilter=Artist|LicenseShortName")){
        (q.pages||[]).forEach(pg=>{ const m=pg.imageinfo?.[0]?.extmetadata; if(m) meta[pg.title.replace(/^File:/,"")]={artist:stripTags(m.Artist?.value),license:stripTags(m.LicenseShortName?.value),commons:true}; });
      }
      Object.values(p).forEach(x=>{ if(meta[x.file]) Object.assign(x,meta[x.file]); });
    }catch(e){}
    PHOTO = p;
    try{ localStorage.setItem(PHOTO_KEY, JSON.stringify({t:Date.now(),p})); }catch(e){}
    render();
  }catch(e){ /* 사진을 못 받으면 한자 그래픽·빈 자리를 그대로 보여줌 */ }
}
/* 가게 사진 고르기: 직접 넣은 사진(RESTAURANT_PHOTOS, 현재 사용 안 함) → 위키 사진 → 예시/없음 */
