/* weather: Open-Meteo (API 키 불필요) */
const COORD = {tokyo:[35.681,139.767],osaka:[34.702,135.495],fukuoka:[33.590,130.420],hokkaido:[43.069,141.351],okinawa:[26.212,127.681]};
Object.values(AREA).forEach(a=>COORD[a.key]=[a.lat,a.lng]);
let WX = null, wxFailed = false;
function wicon(c){
  if(c==null) return "🌤️";
  if(c===0) return "☀️"; if(c<=2) return "🌤️"; if(c===3) return "☁️"; if(c===45||c===48) return "🌫️";
  if(c>=51&&c<=57) return "🌦️"; if(c>=61&&c<=67) return "🌧️"; if(c>=71&&c<=77) return "🌨️"; if(c>=80&&c<=82) return "🌦️";
  if(c===85||c===86) return "❄️"; if(c>=95) return "⛈️"; return "🌤️";
}
function wmo(c){
  if(c===0) return "맑음"; if(c<=2) return "구름 조금"; if(c===3) return "흐림"; if(c===45||c===48) return "안개";
  if(c>=51&&c<=57) return "이슬비"; if(c>=61&&c<=67) return "비"; if(c>=71&&c<=77) return "눈"; if(c>=80&&c<=82) return "소나기";
  if(c===85||c===86) return "눈보라"; if(c>=95) return "뇌우"; return "–";
}
async function loadWeather(){
  try{
    const ks = Object.keys(COORD);
    const url = "https://api.open-meteo.com/v1/forecast?latitude="+ks.map(k=>COORD[k][0]).join(",")+"&longitude="+ks.map(k=>COORD[k][1]).join(",")+
      "&current=temperature_2m,apparent_temperature,weather_code,relative_humidity_2m&hourly=temperature_2m,weather_code,precipitation_probability,wind_speed_10m,relative_humidity_2m&wind_speed_unit=ms&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=Asia%2FTokyo&forecast_days=7";
    const r = await fetch(url); if(!r.ok) throw new Error("wx "+r.status);
    let j = await r.json(); if(!Array.isArray(j)) j=[j];
    const w = {}; ks.forEach((k,i)=>{ if(j[i]&&j[i].current) w[k]=j[i]; });
    WX = w; wxFailed = false;
  }catch(e){ wxFailed = true; }
  renderCities();
}
const rnd = n => Math.round(n);
const DOW = ["일","월","화","수","목","금","토"];
/* 일본 현재 시각 (JST) */
function jstParts(){
  const f = new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Tokyo",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23",weekday:"short"});
  const o = {}; f.formatToParts(new Date()).forEach(p=>o[p.type]=p.value);
  const wd = {Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6}[o.weekday];
  return {date:`${o.year}-${o.month}-${o.day}`,hour:o.hour,min:o.minute,dow:DOW[wd],md:`${+o.month}월 ${+o.day}일`};
}
let lastHour = jstParts().hour;
setInterval(()=>{
  const j = jstParts();
  document.querySelectorAll(".jstclock").forEach(el=>el.textContent=`${j.md}(${j.dow}) ${j.hour}:${j.min}`);
  if(j.hour!==lastHour){ lastHour=j.hour; renderCities(); }
},20000);

