/* 시간별 날씨: 탭(날씨·강수·바람·습도) + 꺾은선 그래프 + 날씨 그림 */
const WXTABS = {t:{ko:"날씨",key:"temperature_2m",unit:"°"},p:{ko:"강수",key:"precipitation_probability",unit:"%"},w:{ko:"바람",key:"wind_speed_10m",unit:"m/s"},h:{ko:"습도",key:"relative_humidity_2m",unit:"%"}};
function hourlyChart(h, hi){
  const N = 24, CW = 54, H = 64, PAD = 22;
  const tab = WXTABS[st.wxTab] || WXTABS.t;
  const idx = Array.from({length:N},(_,k)=>hi+k).filter(i=>i<h.time.length);
  const vals = idx.map(i=>h[tab.key]?.[i]);
  const nums = vals.filter(v=>v!=null);
  const lo = Math.min(...nums), hiV = Math.max(...nums), span = (hiV-lo)||1;
  const y = v => v==null ? H+PAD : PAD + (1-(v-lo)/span)*H;
  const W = idx.length*CW;
  const pts = vals.map((v,k)=>`${k*CW+CW/2},${y(v).toFixed(1)}`).join(" ");
  const fmt = v => v==null ? "–" : (tab.key==="wind_speed_10m" ? (Math.round(v*10)/10) : Math.round(v)) + tab.unit;
  const svg = `<svg class="wxsvg" width="${W}" height="${H+PAD*2}" viewBox="0 0 ${W} ${H+PAD*2}" aria-hidden="true">
    <polyline points="${pts}" fill="none" stroke="var(--line-strong,#B9BEC9)" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>
    ${vals.map((v,k)=>`<line x1="${k*CW+CW/2}" x2="${k*CW+CW/2}" y1="${y(v)+5}" y2="${H+PAD*2}" stroke="var(--line)" stroke-width="1"/>
      <circle cx="${k*CW+CW/2}" cy="${y(v)}" r="${k===0?4.5:3}" fill="${k===0?"var(--shu)":"var(--surface)"}" stroke="${k===0?"var(--shu)":"#B9BEC9"}" stroke-width="1.5"/>
      <text x="${k*CW+CW/2}" y="${y(v)-9}" text-anchor="middle" class="${k===0?"now":""}">${fmt(v)}</text>`).join("")}
  </svg>`;
  const cols = idx.map((i,k)=>{ const hh=h.time[i].slice(11,13); const label = k===0?"지금":hh==="00"?`<span class="tmr">내일</span>`:`${+hh}시`;
    return `<div class="wxcol"><span class="wxi" title="${wmo(h.weather_code[i])}">${wicon(h.weather_code[i])}</span><span class="wxh">${label}</span></div>`; }).join("");
  return `<div class="wxhourly"><div class="wxtabs" role="tablist">${Object.entries(WXTABS).map(([k,v])=>`<button type="button" class="wxtab" role="tab" data-wxtab="${k}" aria-selected="${(st.wxTab||"t")===k}">${v.ko}</button>`).join("")}</div>
    <div class="wxscroll"><div class="wxplot" style="width:${W}px">${svg}<div class="wxcols">${cols}</div></div></div></div>`;
}

/* header pieces */
