const AREA_SHOP = {"shinjuku": ["백화점 지하의 도쿄 한정 과자, 드럭스토어 화장품·상비약", "이세탄·다카시마야 같은 백화점과 돈키호테·빅카메라가 모여 있어요. 할인점은 밤늦게까지 열어요."], "shibuya": ["캐릭터 굿즈(시부야 파르코의 포켓몬센터·닌텐도 매장), 트렌드 패션·잡화", "시부야 스크램블 스퀘어·파르코·미야시타 파크 등 큰 쇼핑몰이 역 주변에 모여 있어요. 주말 오후는 매우 붐벼요."], "ginza": ["긴자 노포의 화과자·센베이, 쓰키지 장외시장의 칼·건어물·차", "쓰키지 장외시장은 아침 일찍 열고 오후 2시 무렵이면 많이 닫아요. 일요일·공휴일엔 쉬는 가게가 많아요."], "asakusa": ["나카미세의 닌교야키·센베이, 아메요코의 과자·건어물, 갓파바시 도구거리의 칼·식기", "나카미세는 저녁 6~7시면 대부분 닫아요. 갓파바시는 일요일에 쉬는 가게가 많아요."], "tokyoeki": ["도쿄역 한정 과자, 도쿄 바나나, 에키벤(역 도시락)", "개찰구 안 '그란스타'와 개찰구 밖 '도쿄 오카시랜드'에 선물 가게가 모여 있어요. 떠나는 날 한 번에 사기 좋아요."], "yokohama": ["기요켄 시우마이, 차이나타운의 니쿠만·월병, 빨간 벽돌 창고의 잡화", "요코하마역 백화점(소고·다카시마야) 지하 식품관에서 시우마이와 선물 과자를 한 번에 살 수 있어요."], "kamakura": ["하토 사브레(비둘기 모양 버터 쿠키), 고마치도리의 센베이·말차 간식", "고마치도리는 저녁 5~6시면 문을 닫는 가게가 많아요. 주말 오후는 매우 붐벼요."], "hakone": ["하코네 요세기자이쿠(나무 쪽매붙임 공예)·비밀상자, 온천 만주, 오와쿠다니 검은 달걀", "하코네유모토 역 앞 상점가가 가장 크고, 산 위 가게는 일찍 닫아요."], "dotonbori": ["551 호라이 부타만(당일 먹기), 타코야키·오코노미야키 맛 과자, 오사카 한정 굿즈", "신사이바시스지 상점가와 돈키호테 도톤보리점이 가깝고, 할인점은 밤늦게까지 열어요."], "umeda": ["한큐·한신 백화점 지하의 오사카 한정 과자, 551 호라이 부타만, 포켓몬센터·닌텐도 오사카 굿즈", "한큐·한신·다이마루 백화점이 역 바로 옆에 붙어 있어 비 오는 날 쇼핑하기 좋아요."], "shinsekai": ["쓰루하시 시장의 김치·한국 식재료, 빌리켄 기념품, 구시카쓰 소스", "큰 쇼핑은 덴노지의 아베노 하루카스 긴테쓰 백화점에서 하면 편해요. 쓰루하시 시장은 저녁 일찍 닫는 가게가 많아요."], "tenma": ["덴진바시스지 상점가의 츠케모노(절임)·노포 과자, 싼 생활 잡화", "일본에서 가장 긴 상점가(약 2.6km)라 걸을 구간을 정해 두세요."], "kyoto": ["야쓰하시, 우지 말차 과자, 교토 츠케모노(절임), 교센스(부채)", "니시키 시장은 저녁 일찍 닫으니 낮에 가세요. 교토역 쇼핑몰은 늦게까지 열어 떠나는 날 사기 좋아요."], "nara": ["사슴 모양 과자·굿즈, 나라즈케(술지게미 절임), 나라 먹·붓", "나라공원 주변 기념품점은 저녁 일찍 닫아요. 긴테쓰나라역 앞 히가시무키 상점가가 편해요."], "kobe": ["고베 양과자(푸딩·바움쿠헨·쿠키), 고베 커피, 난킨마치 중화 간식", "산노미야~모토마치 상점가와 다이마루 고베점에 양과자점이 많이 모여 있어요."], "hakata": ["멘타이코(명란젓), 하카타 도리몬, 히요코 만주, 아마오우 딸기 과자", "하카타역의 아뮤플라자·데이토스·한큐 백화점에 선물용 과자가 몰려 있어요."], "tenjin": ["다이묘 골목의 패션·잡화, 텐진 백화점 지하 과자, 멘타이코", "텐진 지하상가는 보통 오전 10시~오후 8시에 열어요. 비 오는 날에도 걷기 좋아요."], "nakasu": ["하카타 라멘 즉석 제품, 멘타이코, 하카타 인형(전통 공예)", "캐널시티 하카타에 브랜드 매장과 캐릭터 숍이 모여 있어요. 가와바타 상점가엔 오래된 가게가 많아요."], "dazaifu": ["우메가에모치(매화 문양 찹쌀떡), 학업 부적·에마", "참배길 가게는 저녁 5~6시면 대부분 닫아요. 우메가에모치는 갓 구운 걸 바로 먹는 게 가장 맛있어요."], "itoshima": ["이토시마 소금, 수제 잼·빵, 해산물 가공품", "가게가 흩어져 있어 렌터카가 편해요. 직판장 '이토사이사이'에서 지역 농산물을 살 수 있어요."], "yufuin": ["롤케이크·푸딩 같은 디저트, 유즈코쇼(유자 후추), 공예 잡화", "유노쓰보 거리 가게는 저녁 5시 전후로 닫아요. 낮에는 매우 붐비니 오전에 가면 좋아요."], "beppu": ["온천 입욕제(유노하나), 지옥찜 푸딩, 벳푸 대나무 공예", "묘반 온천의 유노하나 오두막에서 입욕제를 직접 볼 수 있어요. 벳푸역 주변 상점가도 둘러볼 만해요."], "susukino": ["시로이 고이비토, 로이스 초콜릿, 롯카테이 버터샌드, 수프카레 즉석 제품", "다누키코지 상점가의 드럭스토어와 돈키호테는 밤늦게까지 열어요."], "sapporoeki": ["홋카이도 유제품 과자, 게·연어 가공품, 삿포로 클래식 맥주 굿즈", "삿포로 스텔라 플레이스·다이마루가 역에 붙어 있어 짐 들고 사기 편해요. 기념품 종류는 신치토세공항이 가장 많아요."], "otaru": ["오르골, 오타루 유리 공예, 르타오 치즈케이크(드부블 프로마주)", "사카이마치 거리 가게는 저녁 6시 전후로 닫아요. 유리 제품은 포장을 단단히 해 달라고 하세요."], "hakodate": ["오징어 가공품(이카메시 등), 트라피스틴 쿠키·버터 캔디, 아침시장 해산물", "아침시장은 이른 아침부터 열고 오후 2시 무렵이면 많이 닫아요. 베이 에어리어의 빨간 벽돌 창고에도 가게가 많아요."], "asahikawa": ["아사히야마 동물원 굿즈, 아사히카와 가구·나무 공예, 지역 술(사케)", "역 앞 이온몰과 헤이와도리 쇼핑공원(보행자 거리)이 쇼핑 중심이에요."], "furano": ["라벤더 상품(오일·향주머니), 후라노 치즈·와인, 멜론 과자", "농장 가게는 계절에 따라 닫는 시간이 다르고 겨울엔 쉬는 곳도 있어요. 가게가 흩어져 있어 렌터카가 편해요."], "kokusai": ["베니이모 타르트, 친스코, 시사 인형, 류큐 유리", "국제거리에는 밤늦게까지 여는 가게가 많아요. 같은 상품도 가게마다 값이 다르니 비교해 보세요."], "naha": ["흑설탕, 시마토가라시(섬 고추), 오리온 맥주 굿즈", "시내 대형 슈퍼에서 과자를 더 싸게 살 수 있고, 나하공항 기념품점도 커요. 생고구마 등 일부 농산물은 오키나와 밖으로 가져갈 수 없어요."], "chubu": ["요미탄 야치문(오키나와 도자기), 아메리칸 빌리지의 잡화, 베니이모 과자", "차탄 아메리칸 빌리지는 밤까지 열고, 요미탄 야치문 마을의 공방은 일찍 닫는 곳이 많아요."], "hokubu": ["파인애플 과자·와인, 츄라우미 수족관 굿즈, 아세로라 상품(모토부)", "가게가 띄엄띄엄 있어 렌터카가 필수예요. 휴게소와 농산물 직판장에 지역 특산품이 많아요."], "ishigaki": ["이시가키 라유(고추기름), 미네사 직물, 섬 소금", "시내 아케이드 상점가(유그레나 몰)가 쇼핑 중심이에요. 생고구마 등 일부 농산물은 섬 밖으로 가져갈 수 없어요."], "miyako": ["유키시오(눈소금) 과자, 망고 과자, 미야코 조후(전통 마직물)", "섬 가게는 일찍 닫는 곳이 많아요. 기념품은 미야코공항에서도 대부분 살 수 있어요."]};
