function pageMeta(){
  const L = (window.I18N&&window.I18N.lang)||"ko", M = PMETA[L]||PMETA.ko, T = window.__tr||(x=>x);
  if(st.view==="home") return {title:T("Nihon Trip · 일본 여행 가이드"), desc:null};
  const key = st.view==="saved" ? "saved" : st.view==="map" ? "map" : (st.city==="all" ? "all_"+st.view : st.view);
  const a = st.city==="all" ? "" : T(curArea()?.ko || CITIES[st.city].ko), c = {ko:"일본",en:"Japan",ja:"日本",es:"Japón",fr:"Japon"}[L];
  const mon = L==="ko" ? st.month+"월" : L==="ja" ? st.month+"月" : (window.I18N.MON[st.month-1]||st.month);
  const names = [...new Set([...document.querySelectorAll("#main .card h3, #main .arlist .nm, #main .fest h3, #main .gname, #main .gift h3")].map(e=>T(e.textContent.trim())).filter(Boolean))].slice(0,4);
  const sep = L==="ja" ? "、" : L==="ko" ? ", " : ", ";
  const Ls = names.length ? M.L.replace("{n}", names.join(sep)) : "";
  const f = (x)=> (x||"").replace(/\{a\}/g,a).replace(/\{c\}/g,c).replace(/\{m\}/g,mon).replace("{L}",Ls);
  return {title: f(M.t[key]) + " | Nihon Trip", desc: M.d[key] ? f(M.d[key]) : null};
}
function setMeta(sel,val){ const m=document.querySelector(sel); if(m&&val) m.setAttribute("content",val); }
function syncUrl(){
  if(!ROUTED) return;
  const want = window.NT_BASE + LPRE + pathOf(st);
  if(location.pathname!==want){ try{ history.pushState(null,"",want) }catch(_){} }
  const pm = pageMeta(); document.title = pm.title; setMeta('meta[property="og:title"]',pm.title);
  if(pm.desc){ setMeta('meta[name="description"]',pm.desc); setMeta('meta[property="og:description"]',pm.desc); }
}
window.addEventListener("popstate",()=>{ if(ROUTED){ readPath(); st.q=""; st.focus=null; render(); } });

function render(){
  document.body.classList.toggle("is-map", st.view==="map");
  if(st.view!=="map" && MAP){ try{ MAP.remove(); }catch(_){} MAP=null; MAPREADY=false; }
  if(st.view==="map"){ setNav(); const mw=$("#mapwrap"); if(!mw || !mw.dataset.live){ $("#main").innerHTML = V.map(); $("#mapwrap").dataset.live="1"; mapMount(); } else mapListRender(); syncUrl(); return; }
  if(st.view==="home"){ st.city="all"; }
  if(st.city==="all") st.area="all";
  if(st.city!=="all" && (st.area==="all" || !areasOf(st.city).some(a=>a.key===st.area))) st.area = areasOf(st.city)[0]?.key || "all";
  renderCities(); setNav();
  $("#main").innerHTML = V[st.view]();
  const q = $("#q");
  if(q) q.addEventListener("input",e=>{st.q=e.target.value;const pos=e.target.selectionStart;render();const n=$("#q");n.focus();n.setSelectionRange(pos,pos)});
  syncUrl();
}

/* drawer */
let lastFocus=null;
function restGallery(r){
  const ph = restPhotos(r);
  const tile = (x,label,note,empty) => `<figure class="gtile">${x
      ? `<div class="gimg"><img src="${esc(x.src)}" alt="${esc(r.name)} ${label}" decoding="async" referrerpolicy="no-referrer"><span class="glabel">${label}${note?` · ${note}`:""}</span></div><figcaption>${creditHTML(x)}</figcaption>`
      : `<div class="gimg gempty"><span class="glabel">${label}</span><p>${empty}</p></div><figcaption>&nbsp;</figcaption>`}</figure>`;
  return `<div class="gallery">
    ${tile(ph.food,"대표 음식",ph.food?.example?"예시 사진":"",`${esc(r.dish)}<br>사진 준비 중`)}
    ${tile(ph.shop,"가게 입구·내부",ph.shop?.brand?"브랜드 사진 · 지점이 다를 수 있음":"",`직접 찍은 사진을 준비 중이에요.<br><a href="${gmapLink(r)}" target="_blank" rel="noopener">Google 지도에서 가게 사진 보기 ↗</a>`)}
  </div>`;
}
function openItem(id){
  const it = byId(id); if(!it) return;
  lastFocus=document.activeElement;
  const c = CITIES[it.city], isSaved = saved.includes(it.id);
  const facts = [["지역",`${c.ko}${it.sub&&AREA[it.sub]?" · "+AREA[it.sub].ko:""}`]];
  if(it.dish) facts.push(["대표 메뉴",it.dish]);
  if(it.when) facts.push(["시기",it.when]);
  if(it.area) facts.push(["위치",it.area]);
  if(it.station) facts.push(["가는 길",it.station]);
  if(it.price) facts.push(["가격대","¥".repeat(it.price)+" (3단계 중 "+it.price+")"]);
  const mq = encodeURIComponent(`${it.jp} ${it.sub?placeQ(it):c.jp}`);
  $("#drawer").innerHTML = `<button class="close" type="button" id="closeD" aria-label="닫기">×</button>
   ${it.type==="rest" ? restGallery(it) : `<div class="plate" style="--c:var(${colorOf(it)})"><span class="tag">${esc(tagOf(it))}</span><span class="k">${itemIcon(it)}</span>${imgTag(it.id)}</div>`}
   <div class="in"><h2>${esc(it.name)}</h2><div class="jpn">${esc(it.jp)}</div><p>${esc(it.desc)}</p>
   <dl class="facts">${facts.map(([a,b])=>`<dt>${a}</dt><dd>${esc(b)}</dd>`).join("")}</dl>
   ${SHOP_PICKS[it.id]&&it.type==="shop"?`<div class="picks2"><b>추천 쇼핑 목록</b><ul>${SHOP_PICKS[it.id].map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>`:""}
   ${it.tip?`<div class="tip"><b>여행 팁</b> · ${esc(it.tip)}</div>`:""}
   ${it.type==="rest"?`<p class="credit">별점과 리뷰는 아래 링크에서 확인하세요. 영업시간·휴무일도 방문 전에 확인하는 게 좋아요.</p>`:""}
   <div class="actions"><button class="btn${isSaved?"":" primary"}" type="button" id="toggleSave">${isSaved?"나의 여행에서 빼기":"나의 여행에 저장"}</button>
   <a class="btn" href="https://www.google.com/maps/search/?api=1&query=${mq}" target="_blank" rel="noopener">${it.type==="rest"?"Google 지도 평점 ↗":"지도에서 보기 ↗"}</a>
</div>
   ${it.type!=="rest"&&PHOTO[it.id]?`<div class="credit">사진:${esc(PHOTO[it.id].artist||"저작자 정보는 원본 참고")}${PHOTO[it.id].license?" · "+esc(PHOTO[it.id].license):""} · <a href="${PHOTO[it.id].lang==="ja"&&!PHOTO[it.id].commons?"https://ja.wikipedia.org/wiki/File:":"https://commons.wikimedia.org/wiki/File:"}${encodeURIComponent(PHOTO[it.id].file.replace(/ /g,"_"))}" target="_blank" rel="noopener">사진 원본 ↗</a></div>`:""}</div>`;
  $("#drawer").hidden=false; $("#scrim").hidden=false;
  $("#closeD").focus();
  $("#closeD").onclick=closeItem;
  $("#toggleSave").onclick=()=>{ saved = saved.includes(it.id)? saved.filter(x=>x!==it.id) : [...saved,it.id]; persist(); render(); openItem(it.id); };
}
function closeItem(){ $("#drawer").hidden=true; $("#scrim").hidden=true; if(lastFocus&&lastFocus.focus) lastFocus.focus(); }
$("#scrim").onclick=closeItem;
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("#drawer").hidden) closeItem()});

/* events */
document.addEventListener("click",e=>{
  // 이달 추천 도시: 관련 하위 지역·페이지로 이동하고 추천 항목을 맨 위에 보여줌
  const rc = e.target.closest("[data-rec]");
  if(rc){ const [k,why,t] = (MONTH_PICKS[(st.hm||NOW_M)-1]||[])[+rc.dataset.rec]||[]; if(k){ st.city=k; st.area=t.area||"all"; st.view=t.view||"spots"; if(t.month) st.month=t.month; st.focus={ids:t.ids||[],why,city:k,m:st.hm||NOW_M}; st.more=false; if(!ROUTED){ try{history.replaceState(null,"","#"+st.view)}catch(_){} } render(); window.scrollTo({top:0}); } return; }
  if(e.target.closest("[data-city],[data-area],[data-view],[data-chip],[data-month]")) st.focus=null;
  const v = e.target.closest("[data-view]");
  if(v){ e.preventDefault(); go(v.dataset.view); return; }
  const hmb = e.target.closest("[data-hm]"); if(hmb){ st.hm=+hmb.dataset.hm; renderCities(); return; }
  const ht = e.target.closest("[data-hometo]"); if(ht){ st.homeTo=ht.dataset.hometo; render(); return; }
  const ga = e.target.closest("[data-goarea]");
  if(ga){ st.city=ga.dataset.region; st.area=ga.dataset.goarea; st.focus=null; st.more=false; go(ga.dataset.to||st.homeTo); return; }
  const hc = e.target.closest("[data-city]");
  if(hc && st.view==="home" && hc.dataset.city!=="all"){ st.city=hc.dataset.city; st.area="all"; st.focus=null; go(st.homeTo); return; }
  const c = e.target.closest("[data-city]"); if(c){ st.city=c.dataset.city; st.area="all"; st.more=false; render(); return; }
  const ar = e.target.closest("[data-area]"); if(ar){ if(ar.dataset.region) st.city=ar.dataset.region; st.area=ar.dataset.area; st.more=false; render(); if(ar.dataset.region || st.view==="food") window.scrollTo({top:0}); return; }
  if(e.target.closest("#moreBtn")){ st.more=!st.more; render(); return; }
  const wt = e.target.closest("[data-wxtab]"); if(wt){ st.wxTab = wt.dataset.wxtab; renderCities(); return; }
  const ch = e.target.closest("[data-chip]"); if(ch){ st[ch.dataset.chip]=ch.dataset.v; render(); return; }
  const m = e.target.closest("[data-month]"); if(m){ st.month=+m.dataset.month; render(); return; }
  const o = e.target.closest("[data-open]"); if(o){ openItem(o.dataset.open); return; }
});
$("#savedBtn").onclick=()=>go("saved");
/* 언어 선택 — 고르면 저장하고 새로고침해서 그 언어 사전으로 다시 그려요 */
const LANGS=[["ko","KR","한국어"],["en","EN","English"],["ja","JP","日本語"],["es","ES","Español"],["fr","FR","Français"]];
let LANG=(window.I18N&&window.I18N.lang)||"ko";
function renderLang(){
  const cur=LANGS.find(l=>l[0]===LANG)||LANGS[0]; $("#langCode").textContent=cur[1]; document.documentElement.lang=LANG;
  $("#langMenu").innerHTML=LANGS.map(([k,code,name])=>`<button type="button" role="menuitemradio" class="notranslate" lang="${k}" data-lang="${k}" aria-checked="${k===LANG}">${name}<small>${k===LANG?"✓":""}</small></button>`).join("");
}
renderLang();
$("#langBtn").onclick=e=>{ e.stopPropagation(); const m=$("#langMenu"); m.hidden=!m.hidden; $("#langBtn").setAttribute("aria-expanded",String(!m.hidden)); };
$("#langMenu").onclick=e=>{ e.stopPropagation(); const b=e.target.closest("[data-lang]"); if(!b) return; $("#langMenu").hidden=true; if(b.dataset.lang===LANG) return; try{localStorage.setItem("tabishiori-lang",b.dataset.lang)}catch(_){} if(ROUTED){ location.href = window.NT_BASE + (b.dataset.lang==="ko"?"":b.dataset.lang+"/") + pathOf(st); return; } const u=new URL(location.href); u.searchParams.set("lang",b.dataset.lang); location.replace(u.toString()); };
document.addEventListener("click",()=>{ if(!$("#langMenu").hidden){ $("#langMenu").hidden=true; $("#langBtn").setAttribute("aria-expanded","false"); } });
function go(view){
  if(!VIEWS.includes(view)) view="spots";
  st.view=view; st.q="";
  if(view==="home"){ st.city="all"; st.area="all"; st.focus=null; }
  if(!ROUTED){ try{history.replaceState(null,"","#"+view)}catch(e){} }
  render(); window.scrollTo({top:0});
}
if(ROUTED) readPath();
else { const h = (location.hash||"").slice(1); if(VIEWS.includes(h)) st.view=h; }
render();
if(ROUTED) try{ history.replaceState(null,"",window.NT_BASE + LPRE + pathOf(st)); }catch(_){}
